const works = [
 {id:'midia', title:'Mídia, a Grande Mentira', category:'cinema', label:'CINEMA', year:'1999', format:'Curta-metragem · Super 8', teaser:'Imagem, poder e pensamento.', description:'Um curta de crítica ao poder dos meios de comunicação. A dissertação de Tânia Olivatti, na Unesp, analisa a construção visual e sonora do filme e sua relação com uma oficina da Cooperfilmes, em Taubaté.', note:'Data e formato registrados no currículo artístico de 2022. A análise acadêmica pode ser consultada na fonte abaixo.', source:sources.unesp, art:'midia', kicker:'UM FILME DE MÁRCIO VACCARI', typography:'MÍDIA,<br>A GRANDE<br><em>MENTIRA.</em>', footer:'CINEMA DE INVENÇÃO / 1999'},
 {id:'santo', title:'Santo de Casa', category:'cinema visual', label:'CINEMA EXPERIMENTAL', year:'LONGA', format:'Carne Esticada na Máquina', teaser:'O corpo como linguagem.', description:'Longa associado à proposta estética Carne Esticada na Máquina, registrada no currículo do cineasta. O trabalho aproxima experimentação audiovisual e presença corporal.', note:'As fontes divergem: o currículo de 2022 indica 2014, enquanto um currículo posterior indica 2013. A data permanece aberta neste acervo.', source:sources.profile, art:'santo', kicker:'CARNE ESTICADA NA MÁQUINA', typography:'santo<br><em>de casa</em><span class="art-cross">+</span>',footer:'UM LONGA DE MÁRCIO VACCARI'},
 {id:'gema', title:'A Gema do Novo', category:'tela', label:'INTERNET', year:'2004', format:'Direção · Série de entrevistas', teaser:'Encontros da cena independente.', description:'Programa dirigido por Vaccari, com entrevistas de artistas como Mário Bortolotto, Paulão de Carvalho, Edvaldo Santana e Paulo de Tharso. Teatro, música e cinema se cruzam nessas conversas.', note:'O currículo publicado em projeto cultural registra o programa em 2004; os convidados são citados no verbete biográfico.', source:sources.wiki, art:'gema', kicker:'ARTISTAS EM CONVERSA',typography:'a gema<br>do <em>novo</em><span class="art-star">✳</span>',footer:'DIREÇÃO / MÁRCIO VACCARI'},
 {id:'boilesen',title:'Boilesen',category:'cinema',label:'CINEMA / SUPER 8',year:'1976',format:'Curta-metragem',description:'Um dos microfilmes em Super 8 listados no currículo artístico do cineasta.',note:'Título, formato e ano conforme currículo publicado no projeto Fórum Vale Poético de 2022.',source:sources.curriculum},
 {id:'lili',title:'Lili Foi Dar Aula de Geografia e Sumiu do Mapa',category:'cinema',label:'CINEMA / SUPER 8',year:'1977',format:'Curta-metragem',description:'Microfilme cuja construção poética começa no próprio título. Integra a produção experimental de Vaccari em Super 8.',note:'Adotamos 1977, data do currículo de 2022. O perfil do autor no Clube de Autores apresenta outra data para o título.',source:sources.curriculum},
 {id:'beat',title:'Beat Vale',category:'cinema',label:'CINEMA / 16 MM',year:'LONGA',format:'Longa-metragem',description:'Longa de Vaccari registrado em 16 mm no currículo de 2022. O universo das filmagens também aparece na sinopse de seu livro Carne em Brasa.',note:'O currículo de 2022 informa 1995; outro currículo registra 1992. Este acervo não fixa um ano enquanto houver divergência.',source:sources.curriculum},
 {id:'humor',title:'Vale Humor',category:'cena tela',label:'ATUAÇÃO',year:'DESDE 2013',format:'Coletivo de comédia',description:'Vaccari integra o coletivo Vale Humor, criado em 2013 para pesquisar a linguagem cômica e produzir esquetes audiovisuais. Sua participação aparece nos registros como ator.',note:'O currículo distingue Márcio Vaccari de Júnior Vaccari, fundador e diretor do coletivo. A direção dos trabalhos do filho não é atribuída ao pai.',source:sources.forum},
 {id:'causos',title:'Causos e Canções',category:'cena',label:'TEATRO / MÚSICA',year:'PROJETO 2023',format:'Espetáculo músico-teatral',description:'No projeto, Márcio Vaccari e Alley Anderson recebem convidados para compartilhar canções e histórias do Vale do Paraíba. Vaccari participa como ator, apresentador e contador de histórias, com acompanhamento musical de Alley.',note:'O documento de 2023 descreve a proposta de montagem. A apresentação do projeto não equivale a um registro de todas as sessões realizadas.',source:sources.causos},
 {id:'triangulo',title:'Triângulo das Bermudas',category:'cena',label:'TEATRO',year:'INTERPRETAÇÃO',format:'Pesquisa de linguagem cênica',description:'Método de interpretação atribuído a Vaccari em seu currículo, que o situa também como criador e pesquisador de processos teatrais.',note:'Informação curricular declarada no projeto cultural. Não foi localizado, nesta pesquisa, um manual publicado do método.',source:sources.profile},
 {id:'tv',title:'A música em Malhação',category:'tela',label:'TELEVISÃO',year:'COMPOSIÇÃO',format:'Perdidos na Selva · Trilha sonora',description:'Perdidos na Selva, parceria com Júlio Barroso e Guilherme Arantes, integrou a trilha de Malhação, na TV Globo. É uma conexão documentada entre sua composição e a televisão.',note:'O verbete também menciona participações em novelas e publicidade, sem identificar títulos e personagens. Esses créditos específicos não foram catalogados.',source:sources.wiki},
 {id:'visual',title:'A imagem como matéria',category:'visual',label:'ARTES PLÁSTICAS',year:'CINEMA',format:'Intersecções entre linguagens',description:'A atuação como artista visual aparece no currículo de Vaccari. No verbete biográfico, sua estética cinematográfica é descrita pela aproximação entre artes plásticas e poesia.',note:'Não há, no material verificado, fichas suficientes para atribuir pinturas, esculturas ou exposições individuais específicas. As duas fotos deste site vieram da pasta fornecida, sem autoria fotográfica informada.',source:sources.curriculum},
 {id:'forum',title:'Fórum Vale Poético',category:'cena visual',label:'POESIA / CURADORIA',year:'DESDE 2010',format:'Encontros e curadoria de poemas',description:'Co-criador do Fórum Vale Poético, Vaccari participa da organização e da curadoria de poemas. Um currículo público lista sete edições: 2010, 2012, 2014, 2016, 2018, 2022 e 2024.',note:'O projeto articula poesia e outras linguagens. O registro de 2022 apresenta Vaccari como diretor artístico.',source:sources.forum}
];
const grid=document.querySelector('#works-grid');
works.forEach((work,index)=>{
 const article=document.createElement('article'); article.className='work-card'+(work.art?'':' compact'); article.dataset.category=work.category;
 const button=document.createElement('button');button.className='work-open';button.dataset.work=work.id;button.setAttribute('aria-haspopup','dialog');
 if(work.art){button.innerHTML=`<span class="work-art art-${work.art}" aria-hidden="true"><span class="art-kicker">${work.kicker}</span><span class="art-title">${work.typography}</span><span class="art-footer">${work.footer}</span><span class="open-icon">↗</span></span><span class="work-meta">${work.label}<span>${work.year}</span></span><h3>${work.title}</h3><span class="work-description">${work.teaser}</span>`;}
 else {button.innerHTML=`<span class="work-index" aria-hidden="true">${String(index+1).padStart(2,'0')}</span><span class="compact-body"><span class="work-meta">${work.label} · ${work.year}</span><h3>${work.title}</h3></span><span class="compact-arrow" aria-hidden="true">↗</span>`;}
 article.append(button);grid.append(article);
});
const filterButtons=document.querySelectorAll('[data-filter]');
filterButtons.forEach(button=>button.addEventListener('click',()=>{
 filterButtons.forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 let count=0;document.querySelectorAll('.work-card').forEach(card=>{const visible=button.dataset.filter==='all'||card.dataset.category.split(' ').includes(button.dataset.filter);card.hidden=!visible;if(visible)count++;});
 document.querySelector('#filter-status').textContent=`${count} trabalhos exibidos.`;
}));
const dialog=document.querySelector('#work-dialog');let lastTrigger=null;
grid.addEventListener('click',event=>{const trigger=event.target.closest('[data-work]');if(!trigger)return;const work=works.find(w=>w.id===trigger.dataset.work);lastTrigger=trigger;document.querySelector('#dialog-category').textContent=work.label+' / '+work.format;document.querySelector('#dialog-title').textContent=work.title;document.querySelector('#dialog-description').textContent=work.description;document.querySelector('#dialog-note').textContent=work.note;document.querySelector('#dialog-source').href=work.source;dialog.showModal();document.body.classList.add('dialog-open');});
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
dialog.addEventListener('close',()=>{document.body.classList.remove('dialog-open');lastTrigger?.focus();});
const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('#navigation');
function closeMenu(){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');menu.querySelector('span').textContent='+';}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);menu.querySelector('span').textContent=open?'−':'+';});
nav.addEventListener('click',event=>{if(event.target.closest('a'))closeMenu();});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();});
